Now create an example package that uses testify for assertions and mocking. Let me design:

`internal/weather` or `greeter`? Let's make a service that depends on an external HTTP-ish dependency, so a mock is natural.

Example: package `notify` with an `EmailSender` interface and a `Notifier` that uses it. Test with testify mock + assert.

Files:
- `notify/notifier.go`
- `notify/notifier_test.go`

Let me design:

```go
package notify

type Sender interface {
    Send(to, message string) error
}

type Notifier struct {
    sender Sender
}

func New(s Sender) *Notifier { return &Notifier{sender: s} }

func (n *Notifier) Notify(to, name string) error {
    if to == "" {
        return errors.New("recipient is required")
    }
    return n.sender.Send(to, "Hello, "+name+"!")
}
```

Test using testify:
```go
package notify

import (
    "errors"
    "testing"

    "github.com/stretchr/testify/assert"
    "github.com/stretchr/testify/mock"
    "github.com/stretchr/testify/require"
)

type mockSender struct{ mock.Mock }

func (m *mockSender) Send(to, message string) error {
    args := m.Called(to, message)
    return args.Error(0)
}

func TestNotify(t *testing.T) {
    sender := new(mockSender)
    sender.On("Send", "a@example.com", "Hello, Ada!").Return(nil)
    n := New(sender)
    require.NoError(t, n.Notify("a@example.com", "Ada"))
    sender.AssertExpectations(t)
}

func TestNotify_RequiresRecipient(t *testing.T) {
    n := New(new(mockSender))
    err := n.Notify("", "Ada")
    require.Error(t, err)
    assert.EqualError(t, err, "recipient is required")
}

func TestNotify_PropagatesSendError(t *testing.T) {
    sender := new(mockSender)
    wantErr := errors.New("smtp down")
    sender.On("Send", mock.Anything, mock.Anything).Return(wantErr)
    err := New(sender).Notify("a@example.com", "Ada")
    require.ErrorIs(t, err, wantErr)
    sender.AssertExpectations(t)
}
```

Good. This demonstrates assert, require, mock, and match argument matchers.

